#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)return 2;auto g=loadGraph(argv[1]);unsigned total=0;for(uint32_t i=0;i<g.elements.size();++i){auto&e=g.elements[i];auto type=g.strings.at(e.type);if(type!="DmeGameModel")continue;std::cout<<"model="<<i<<" name="<<g.strings.at(e.name)<<'\n';for(auto&a:e.attributes){auto name=g.strings.at(a.name);if(name=="modelName"&&a.type==5)std::cout<<"asset="<<a.values.at(0).text<<'\n';if(name=="flexWeights")std::cout<<"flex_weight_count="<<a.values.size()<<" type="<<unsigned(a.type)<<'\n';}unsigned count=0;for(uint32_t j=0;j<g.elements.size();++j){auto& op=g.elements[j];if(g.strings.at(op.type)!="DmeGlobalFlexControllerOperator")continue;for(auto&a:op.attributes)if(g.strings.at(a.name)=="gameModel"&&a.type==1&&a.values.at(0).reference==i){if(count<8)std::cout<<"operator="<<j<<" name="<<g.strings.at(op.name)<<'\n';++count;++total;}}std::cout<<"linked_flex_operators="<<count<<'\n';}std::cout<<"total_linked_flex_operators="<<total<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
